   "type": "string",
   "required": true,
   "description": "Access token obtained from simple_note app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "note_id": 1,
   "title": "string",
   "content": "string",
   "tags": [
    "string"
   ],
   "created_at": "2019-01-01T00:00:00",
   "updated_at": "2019-01-01T00:00:00",
   "pinned": true
  },
  "failure": {
   "message": "string"
  }
 }
}

