groups_data = apis.splitwise.show_groups(access_token=splitwise_login['access_token'], page_limit=100)
notes_data = {}
for note_id in [3089, 3088, 3086, 3087, 3085, 3084]:
    notes_data[note_id] = apis.simple_note.show_note(note_id=note_id, access_token=simple_note_login['access_token'])

# Build a mapping from group name to group_id and member name->email
group_map = {}
for g in groups_data:
    group_map[g['name']] = g
    # Also store member mapping
    g['member_email'] = {m['name']: m['email'] for m in g['members']}

# Print to verify
for name, g in group_map.items():
    print(f"Group: {name} (id={g['group_id']})")
    print("Members:", g['member_email'])
    print()

